-- myPeers v2 initial schema.
-- Every table uses UUID primary keys generated by Postgres (gen_random_uuid is built in since PG 13).

-- People who can sign in. Demo users are created by "Try the demo" and are
-- isolated from real users (see server/src/services/visibility.ts).
create table users (
  id                uuid primary key default gen_random_uuid(),
  email             text not null,
  name              text not null check (length(name) between 1 and 60),
  password_hash     text,
  email_verified_at timestamptz,
  is_demo           boolean not null default false,
  created_at        timestamptz not null default now()
);
create unique index users_email_key on users (lower(email));

-- Login sessions. We store a SHA-256 hash of the cookie token, never the
-- token itself, so a leaked database cannot be used to log in.
create table auth_sessions (
  id         text primary key,
  user_id    uuid not null references users(id) on delete cascade,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);
create index auth_sessions_user_idx on auth_sessions (user_id);

-- Six-digit codes for email verification and password reset (hashed).
create table email_codes (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references users(id) on delete cascade,
  purpose    text not null check (purpose in ('verify', 'reset')),
  code_hash  text not null,
  attempts   int  not null default 0,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);
create index email_codes_user_purpose_idx on email_codes (user_id, purpose);

-- A "check-in" is what the old app called a session: the course you are
-- studying, what you are working on, and where. One per user.
create table check_ins (
  user_id     uuid primary key references users(id) on delete cascade,
  course_code text not null check (length(course_code) between 3 and 16),
  topic       text not null default '' check (length(topic) <= 80),
  location    text not null default '' check (length(location) <= 60),
  status      text not null default 'studying' check (status in ('studying', 'break')),
  started_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index check_ins_course_idx on check_ins (course_code);

-- Files shared in chat. Bytes live on disk (a Railway volume in production);
-- this row is the metadata plus the owner, used for access checks.
create table attachments (
  id          uuid primary key default gen_random_uuid(),
  uploader_id uuid not null references users(id) on delete cascade,
  file_name   text not null,
  mime_type   text not null,
  size_bytes  int  not null check (size_bytes > 0),
  storage_key text not null unique,
  created_at  timestamptz not null default now()
);

-- One-to-one messages.
create table direct_messages (
  id            uuid primary key default gen_random_uuid(),
  sender_id     uuid not null references users(id) on delete cascade,
  recipient_id  uuid not null references users(id) on delete cascade,
  body          text not null default '' check (length(body) <= 2000),
  attachment_id uuid references attachments(id) on delete set null,
  read_at       timestamptz,
  created_at    timestamptz not null default now(),
  check (sender_id <> recipient_id),
  check (length(body) > 0 or attachment_id is not null)
);
-- Serves "load the thread between A and B, newest first" in either direction.
create index dm_pair_idx on direct_messages
  (least(sender_id, recipient_id), greatest(sender_id, recipient_id), created_at desc);
create index dm_unread_idx on direct_messages (recipient_id) where read_at is null;

-- Study rooms: a shareable code, members, chat, a shared whiteboard and timer.
create table rooms (
  id           uuid primary key default gen_random_uuid(),
  code         text not null unique check (code ~ '^[A-Z0-9]{6}$'),
  name         text not null check (length(name) between 1 and 50),
  course_code  text,
  created_by   uuid not null references users(id) on delete cascade,
  is_demo      boolean not null default false,
  -- Server-authoritative Pomodoro state, see server/src/realtime/timer.ts
  timer        jsonb not null default '{"mode":"focus","durationSec":1500,"endsAt":null,"remainingSec":1500}',
  -- Whiteboard strokes, capped in code so the row stays small.
  whiteboard   jsonb not null default '[]',
  created_at   timestamptz not null default now()
);

create table room_members (
  room_id   uuid not null references rooms(id) on delete cascade,
  user_id   uuid not null references users(id) on delete cascade,
  joined_at timestamptz not null default now(),
  primary key (room_id, user_id)
);
create index room_members_user_idx on room_members (user_id);

create table room_messages (
  id         uuid primary key default gen_random_uuid(),
  room_id    uuid not null references rooms(id) on delete cascade,
  sender_id  uuid not null references users(id) on delete cascade,
  body       text not null check (length(body) between 1 and 2000),
  created_at timestamptz not null default now()
);
create index room_messages_room_idx on room_messages (room_id, created_at desc);
